//! Backwards-compatible module path for the command result types.
//!
//! The canonical definitions are generated by `mudu_gen` into
//! [`crate::universal::uni_command_result`] (from `uni-command-result.wit`,
//! which declares both `uni-command-result` and `uni-command-return`). This
//! shim keeps the pre-existing `universal::uni_command_return` import path
//! source-compatible.

pub use crate::universal::uni_command_result::{UniCommandResult, UniCommandReturn};

#[cfg(test)]
mod tests {
    use super::{UniCommandResult, UniCommandReturn};
    use crate::universal::mp_wire::{FromValue, ToValue, decode_value, encode_value};
    use crate::universal::uni_error::UniError;

    fn value_roundtrip(value: &UniCommandReturn) -> UniCommandReturn {
        let bytes = encode_value(&value.to_value());
        UniCommandReturn::from_value(&decode_value(&bytes).unwrap()).unwrap()
    }

    #[test]
    fn ok_roundtrip() {
        let value = UniCommandReturn::from_ok(UniCommandResult { affected_rows: 42 });
        let decoded = value_roundtrip(&value);
        assert_eq!(decoded.expect_ok().affected_rows, 42);
    }

    #[test]
    fn err_roundtrip() {
        let value = UniCommandReturn::from_err(UniError {
            err_code: 2,
            err_msg: "not found".to_string(),
            ..Default::default()
        });
        let decoded = value_roundtrip(&value);
        let err = decoded.expect_err();
        assert_eq!(err.err_code, 2);
        assert_eq!(err.err_msg, "not found");
    }

    #[test]
    fn wire_shape_is_tag_payload_array() {
        let value = UniCommandReturn::from_ok(UniCommandResult { affected_rows: 1 });
        let bytes = encode_value(&value.to_value());
        // [0, {1: 1}] — variant 2-array wrapping the record field map.
        assert_eq!(bytes, vec![0x92, 0x00, 0x81, 0x01, 0x01]);
    }

    #[test]
    fn rejects_unknown_tag() {
        // [3, 0] — unknown variant tag.
        let bytes = vec![0x92, 0x03, 0x00];
        assert!(UniCommandReturn::from_value(&decode_value(&bytes).unwrap()).is_err());
    }

    #[test]
    fn accessors_return_none_for_wrong_variant() {
        let ok = UniCommandReturn::from_ok(UniCommandResult::default());
        assert!(ok.as_err().is_none());
        let err = UniCommandReturn::from_err(UniError::default());
        assert!(err.as_ok().is_none());
    }

    #[test]
    fn default_is_ok_with_zero_rows() {
        let value = UniCommandReturn::default();
        assert_eq!(value.expect_ok().affected_rows, 0);
    }
}
